+/** The last matching rule in the ordered list, or undefined if none match. */
+function decidingRule(rules: Rule[], request: AccessRequest): Rule | undefined {
+  let decided: Rule | undefined;
+  for (const rule of rules) {
+    if (matches(rule, request)) decided = rule;
+  }
